00058 const uint8_t IntraPrediction::m_aucIntraFilter[MAX_INTRA_FILTER_DEPTHS] =
00059 {
00060   24, //   1xn
00061   24, //   2xn
00062   24, //   4xn
00063   14, //   8xn
00064   2,  //  16xn
00065   0,  //  32xn
00066   0,  //  64xn
00067   0   // 128xn
