00075 IntraPrediction::IntraPrediction()
00076 :
00077   m_currChromaFormat( NUM_CHROMA_FORMAT )
00078 {
00079   for (uint32_t ch = 0; ch < MAX_NUM_COMPONENT; ch++)
00080   {
00081     for (uint32_t buf = 0; buf < 4; buf++)
00082     {
00083       m_yuvExt2[ch][buf] = nullptr;
00084     }
00085   }
00086 
00087   m_piTemp = nullptr;
00088   m_pMdlmTemp = nullptr;
00089 }
00090 
00091 IntraPrediction::~IntraPrediction()
00092 {
00093   destroy();
00094 }
00095 
00096 void IntraPrediction::destroy()
00097 {
00098   for (uint32_t ch = 0; ch < MAX_NUM_COMPONENT; ch++)
00099   {
00100     for (uint32_t buf = 0; buf < 4; buf++)
00101     {
00102       delete[] m_yuvExt2[ch][buf];
00103       m_yuvExt2[ch][buf] = nullptr;
00104     }
00105   }
00106 
00107   delete[] m_piTemp;
00108   m_piTemp = nullptr;
00109   delete[] m_pMdlmTemp;
00110   m_pMdlmTemp = nullptr;
00111 }
00112 
00113 void IntraPrediction::init(ChromaFormat chromaFormatIDC, const unsigned bitDepthY)
00114 {
00115   if (m_yuvExt2[COMPONENT_Y][0] != nullptr && m_currChromaFormat != chromaFormatIDC)
00116   {
00117     destroy();
00118   }
00119 
00120   m_currChromaFormat = chromaFormatIDC;
00121 
00122 
00123   if (m_yuvExt2[COMPONENT_Y][0] == nullptr) // check if first is null (in which case, nothing initialised yet)
00124   {
00125     m_yuvExtSize2 = (MAX_CU_SIZE) * (MAX_CU_SIZE);
00126 
00127     for (uint32_t ch = 0; ch < MAX_NUM_COMPONENT; ch++)
00128     {
00129       for (uint32_t buf = 0; buf < 4; buf++)
00130       {
00131         m_yuvExt2[ch][buf] = new Pel[m_yuvExtSize2];
00132       }
00133     }
00134   }
00135 
00136   if (m_piTemp == nullptr)
00137   {
00138     m_piTemp = new Pel[(MAX_CU_SIZE + 1) * (MAX_CU_SIZE + 1)];
00139   }
00140   if (m_pMdlmTemp == nullptr)
00141   {
00142     m_pMdlmTemp = new Pel[(2 * MAX_CU_SIZE + 1)*(2 * MAX_CU_SIZE + 1)];//MDLM will use top-above and left-below samples.
00143   }
00144 }
