00150 // Function for calculating DC value of the reference samples used in Intra prediction
00151 //NOTE: Bit-Limit - 25-bit source
00152 Pel IntraPrediction::xGetPredValDc( const CPelBuf &pSrc, const Size &dstSize )
00153 {
00154   CHECK( dstSize.width == 0 || dstSize.height == 0, "Empty area provided" );
00155 
00156   int idx, sum = 0;
00157   Pel dcVal;
00158   const int width  = dstSize.width;
00159   const int height = dstSize.height;
00160   const auto denom     = (width == height) ? (width << 1) : std::max(width,height);
00161   const auto divShift  = floorLog2(denom);
00162   const auto divOffset = (denom >> 1);
00163 
00164   if ( width >= height )
00165   {
00166     for( idx = 0; idx < width; idx++ )
00167     {
00168       sum += pSrc.at(m_ipaParam.multiRefIndex + 1 + idx, 0);
00169     }
00170   }
00171   if ( width <= height )
00172   {
00173     for( idx = 0; idx < height; idx++ )
00174     {
00175       sum += pSrc.at(m_ipaParam.multiRefIndex + 1 + idx, 1);
00176     }
00177   }
00178 
00179   dcVal = (sum + divOffset) >> divShift;
00180   return dcVal;
00181 }
00182 
00183 int IntraPrediction::getModifiedWideAngle( int width, int height, int predMode )
00184 {
00185   //The function returns a 'modified' wide angle index, given that it is not necessary 
00186   //in this software implementation to reserve the values 0 and 1 for Planar and DC to generate the prediction signal.
00187   //It should only be used to obtain the intraPredAngle parameter.
00188   //To simply obtain the wide angle index, the function PU::getWideAngle should be used instead.
00189   if ( predMode > DC_IDX && predMode <= VDIA_IDX )
00190   {
00191     int modeShift[] = { 0, 6, 10, 12, 14, 15 };
00192     int deltaSize = abs(floorLog2(width) - floorLog2(height));
00193     if (width > height && predMode < 2 + modeShift[deltaSize])
00194     {
00195       predMode += (VDIA_IDX - 1);
00196     }
00197     else if (height > width && predMode > VDIA_IDX - modeShift[deltaSize])
00198     {
00199       predMode -= (VDIA_IDX - 1); 
00200     }
00201   }
00202   return predMode;
00203 }
