00205 void IntraPrediction::setReferenceArrayLengths( const CompArea &area )
00206 {
00207   // set Top and Left reference samples length
00208   const int  width    = area.width;
00209   const int  height   = area.height;
00210 
00211   m_leftRefLength     = (height << 1);
00212   m_topRefLength      = (width << 1);
00213 }
