00215 void IntraPrediction::predIntraAng( const ComponentID compId, PelBuf &piPred, const PredictionUnit &pu)
00216 {
00217   const ComponentID    compID       = MAP_CHROMA( compId );
00218   const ChannelType    channelType  = toChannelType( compID );
00219   const int            iWidth       = piPred.width;
00220   const int            iHeight      = piPred.height;
00221   CHECK(iWidth == 2, "Width of 2 is not supported");
00222   CHECK(PU::isMIP(pu, toChannelType(compId)), "We should not get here for MIP.");
00223   const uint32_t       uiDirMode    = isLuma( compId ) && pu.cu->bdpcmMode ? BDPCM_IDX : !isLuma(compId) && pu.cu->bdpcmModeChroma ? BDPCM_IDX : PU::getFinalIntraMode(pu, channelType);
00224 
00225   CHECK( floorLog2(iWidth) < 2 && pu.cs->pcv->noChroma2x2, "Size not allowed" );
00226   CHECK( floorLog2(iWidth) > 7, "Size not allowed" );
00227 
00228   const int srcStride  = m_refBufferStride[compID];
00229   const int srcHStride = 2;
00230 
00231   const CPelBuf & srcBuf = CPelBuf(getPredictorPtr(compID), srcStride, srcHStride);
00232   const ClpRng& clpRng(pu.cu->cs->slice->clpRng(compID));
00233 
00234   switch (uiDirMode)
00235   {
00236     case(PLANAR_IDX): xPredIntraPlanar(srcBuf, piPred); break;
00237     case(DC_IDX):     xPredIntraDc(srcBuf, piPred, channelType, false); break;
00238     case(BDPCM_IDX):  xPredIntraBDPCM(srcBuf, piPred, isLuma(compID) ? pu.cu->bdpcmMode : pu.cu->bdpcmModeChroma, clpRng); break;
00239     default:          xPredIntraAng(srcBuf, piPred, channelType, clpRng); break;
00240   }
00241 
00242   if (m_ipaParam.applyPDPC)
00243   {
00244     PelBuf dstBuf = piPred;
00245     const int scale = ((floorLog2(iWidth) - 2 + floorLog2(iHeight) - 2 + 2) >> 2);
00246     CHECK(scale < 0 || scale > 31, "PDPC: scale < 0 || scale > 31");
00247 
00248     if (uiDirMode == PLANAR_IDX || uiDirMode == DC_IDX)
00249     {
00250       for (int y = 0; y < iHeight; y++)
00251       {
00252         const int wT   = 32 >> std::min(31, ((y << 1) >> scale));
00253         const Pel left = srcBuf.at(y + 1, 1);
00254         for (int x = 0; x < iWidth; x++)
00255         {
00256           const int wL    = 32 >> std::min(31, ((x << 1) >> scale));
00257           const Pel top   = srcBuf.at(x + 1, 0);
00258           const Pel val   = dstBuf.at(x, y);
00259           dstBuf.at(x, y) = val + ((wL * (left - val) + wT * (top - val) + 32) >> 6);
00260         }
00261       }
00262     }
00263   }
00264 }
00265 
00266 void IntraPrediction::predIntraChromaLM(const ComponentID compID, PelBuf &piPred, const PredictionUnit &pu, const CompArea& chromaArea, int intraDir)
00267 {
00268   int  iLumaStride = 0;
00269   PelBuf Temp;
00270   if ((intraDir == MDLM_L_IDX) || (intraDir == MDLM_T_IDX))
00271   {
00272     iLumaStride = 2 * MAX_CU_SIZE + 1;
00273     Temp = PelBuf(m_pMdlmTemp + iLumaStride + 1, iLumaStride, Size(chromaArea));
00274   }
00275   else
00276   {
00277     iLumaStride = MAX_CU_SIZE + 1;
00278     Temp = PelBuf(m_piTemp + iLumaStride + 1, iLumaStride, Size(chromaArea));
00279   }
00280   int a, b, iShift;
00281   xGetLMParameters(pu, compID, chromaArea, a, b, iShift);
00282 
00284   piPred.copyFrom(Temp);
00285   piPred.linearTransform(a, iShift, b, true, pu.cs->slice->clpRng(compID));
00286 }
00287 
00291 //NOTE: Bit-Limit - 24-bit source
00292 void IntraPrediction::xPredIntraPlanar( const CPelBuf &pSrc, PelBuf &pDst )
00293 {
00294   const uint32_t width  = pDst.width;
00295   const uint32_t height = pDst.height;
00296 
00297   const uint32_t log2W = floorLog2( width );
00298   const uint32_t log2H = floorLog2( height );
00299 
00300   int leftColumn[MAX_CU_SIZE + 1], topRow[MAX_CU_SIZE + 1], bottomRow[MAX_CU_SIZE], rightColumn[MAX_CU_SIZE];
00301   const uint32_t offset = 1 << (log2W + log2H);
00302 
00303   // Get left and above reference column and row
00304   CHECK(width > MAX_CU_SIZE, "width greater than limit");
00305   for( int k = 0; k < width + 1; k++ )
00306   {
00307     topRow[k] = pSrc.at( k + 1, 0 );
00308   }
00309 
00310   CHECK(height > MAX_CU_SIZE, "height greater than limit");
00311   for( int k = 0; k < height + 1; k++ )
00312   {
00313     leftColumn[k] = pSrc.at(k + 1, 1);
00314   }
00315 
00316   // Prepare intermediate variables used in interpolation
00317   int bottomLeft = leftColumn[height];
00318   int topRight = topRow[width];
00319 
00320   for( int k = 0; k < width; k++ )
00321   {
00322     bottomRow[k] = bottomLeft - topRow[k];
00323     topRow[k]    = topRow[k] << log2H;
00324   }
00325 
00326   for( int k = 0; k < height; k++ )
00327   {
00328     rightColumn[k] = topRight - leftColumn[k];
00329     leftColumn[k]  = leftColumn[k] << log2W;
00330   }
00331 
00332   const uint32_t finalShift = 1 + log2W + log2H;
00333   const uint32_t stride     = pDst.stride;
00334   Pel*       pred       = pDst.buf;
00335   for( int y = 0; y < height; y++, pred += stride )
00336   {
00337     int horPred = leftColumn[y];
00338 
00339     for( int x = 0; x < width; x++ )
00340     {
00341       horPred += rightColumn[y];
00342       topRow[x] += bottomRow[x];
00343 
00344       int vertPred = topRow[x];
00345       pred[x]      = ( ( horPred << log2H ) + ( vertPred << log2W ) + offset ) >> finalShift;
00346     }
00347   }
00348 }
00349 
00350 void IntraPrediction::xPredIntraDc( const CPelBuf &pSrc, PelBuf &pDst, const ChannelType channelType, const bool enableBoundaryFilter )
00351 {
00352   const Pel dcval = xGetPredValDc( pSrc, pDst );
00353   pDst.fill( dcval );
00354 }
