00356 // Function for initialization of intra prediction parameters
00357 void IntraPrediction::initPredIntraParams(const PredictionUnit & pu, const CompArea area, const SPS& sps)
00358 {
00359   const ComponentID compId = area.compID;
00360   const ChannelType chType = toChannelType(compId);
00361 
00362   const bool        useISP = NOT_INTRA_SUBPARTITIONS != pu.cu->ispMode && isLuma( chType );
00363 
00364   const Size   cuSize    = Size( pu.cu->blocks[compId].width, pu.cu->blocks[compId].height );
00365   const Size   puSize    = Size( area.width, area.height );
00366   const Size&  blockSize = useISP ? cuSize : puSize;
00367   const int      dirMode = PU::getFinalIntraMode(pu, chType);
00368   const int     predMode = getModifiedWideAngle( blockSize.width, blockSize.height, dirMode );
00369 
00370   m_ipaParam.isModeVer            = predMode >= DIA_IDX;
00371   m_ipaParam.multiRefIndex        = isLuma (chType) ? pu.multiRefIdx : 0 ;
00372   m_ipaParam.refFilterFlag        = false;
00373   m_ipaParam.interpolationFlag    = false;
00374   m_ipaParam.applyPDPC            = (puSize.width >= MIN_TB_SIZEY && puSize.height >= MIN_TB_SIZEY) && m_ipaParam.multiRefIndex == 0;
00375 
00376   const int    intraPredAngleMode = (m_ipaParam.isModeVer) ? predMode - VER_IDX : -(predMode - HOR_IDX);
00377 
00378 
00379   int absAng = 0;
00380   if (dirMode > DC_IDX && dirMode < NUM_LUMA_MODE) // intraPredAngle for directional modes
00381   {
00382     static const int angTable[32]    = { 0,    1,    2,    3,    4,    6,     8,   10,   12,   14,   16,   18,   20,   23,   26,   29,   32,   35,   39,  45,  51,  57,  64,  73,  86, 102, 128, 171, 256, 341, 512, 1024 };
00383     static const int invAngTable[32] = {
00384       0,   16384, 8192, 5461, 4096, 2731, 2048, 1638, 1365, 1170, 1024, 910, 819, 712, 630, 565,
00385       512, 468,   420,  364,  321,  287,  256,  224,  191,  161,  128,  96,  64,  48,  32,  16
00386     };   // (512 * 32) / Angle
00387 
00388     const int     absAngMode         = abs(intraPredAngleMode);
00389     const int     signAng            = intraPredAngleMode < 0 ? -1 : 1;
00390                   absAng             = angTable  [absAngMode];
00391 
00392     m_ipaParam.absInvAngle           = invAngTable[absAngMode];
00393     m_ipaParam.intraPredAngle        = signAng * absAng;
00394     if (intraPredAngleMode < 0)
00395     {
00396       m_ipaParam.applyPDPC = false;
00397     }
00398     else if (intraPredAngleMode > 0)
00399     {
00400       const int sideSize = m_ipaParam.isModeVer ? puSize.height : puSize.width;
00401       const int maxScale = 2;
00402 
00403       m_ipaParam.angularScale = std::min(maxScale, floorLog2(sideSize) - (floorLog2(3 * m_ipaParam.absInvAngle - 2) - 8));
00404       m_ipaParam.applyPDPC &= m_ipaParam.angularScale >= 0;
00405     }
00406   }
00407 
00408   // high level conditions and DC intra prediction
00409   if(   sps.getSpsRangeExtension().getIntraSmoothingDisabledFlag()
00410     || !isLuma( chType )
00411     || useISP
00412     || PU::isMIP( pu, chType )
00413     || m_ipaParam.multiRefIndex
00414     || DC_IDX == dirMode
00415     )
00416   {
00417   }
00418   else if ((isLuma(chType) && pu.cu->bdpcmMode) || (!isLuma(chType) && pu.cu->bdpcmModeChroma)) // BDPCM
00419   {
00420     m_ipaParam.refFilterFlag = false;
00421   }
00422   else if (dirMode == PLANAR_IDX) // Planar intra prediction
00423   {
00424     m_ipaParam.refFilterFlag = puSize.width * puSize.height > 32 ? true : false;
00425   }
00426   else if (!useISP)// HOR, VER and angular modes (MDIS)
00427   {
00428     bool filterFlag = false;
00429     {
00430       const int diff = std::min<int>( abs( predMode - HOR_IDX ), abs( predMode - VER_IDX ) );
00431       const int log2Size = ((floorLog2(puSize.width) + floorLog2(puSize.height)) >> 1);
00432       CHECK( log2Size >= MAX_INTRA_FILTER_DEPTHS, "Size not supported" );
00433       filterFlag = (diff > m_aucIntraFilter[log2Size]);
00434     }
00435 
00436     // Selelection of either ([1 2 1] / 4 ) refrence filter OR Gaussian 4-tap interpolation filter
00437     if (filterFlag)
00438     {
00439       const bool isRefFilter       =  isIntegerSlope(absAng);
00440       CHECK( puSize.width * puSize.height <= 32, "DCT-IF interpolation filter is always used for 4x4, 4x8, and 8x4 luma CB" );
00441       m_ipaParam.refFilterFlag     =  isRefFilter;
00442       m_ipaParam.interpolationFlag = !isRefFilter;
00443     }
00444   }
00445 }
