00447 
00458 //NOTE: Bit-Limit - 25-bit source
00459 
00460 void IntraPrediction::xPredIntraAng( const CPelBuf &pSrc, PelBuf &pDst, const ChannelType channelType, const ClpRng& clpRng)
00461 {
00462   int width =int(pDst.width);
00463   int height=int(pDst.height);
00464 
00465   const bool bIsModeVer     = m_ipaParam.isModeVer;
00466   const int  multiRefIdx    = m_ipaParam.multiRefIndex;
00467   const int  intraPredAngle = m_ipaParam.intraPredAngle;
00468   const int  absInvAngle    = m_ipaParam.absInvAngle;
00469 
00470   Pel* refMain;
00471   Pel* refSide;
00472 
00473   Pel  refAbove[2 * MAX_CU_SIZE + 3 + 33 * MAX_REF_LINE_IDX];
00474   Pel  refLeft [2 * MAX_CU_SIZE + 3 + 33 * MAX_REF_LINE_IDX];
00475 
00476   // Initialize the Main and Left reference array.
00477   if (intraPredAngle < 0)
00478   {
00479     for (int x = 0; x <= width + 1 + multiRefIdx; x++)
00480     {
00481       refAbove[x + height] = pSrc.at(x, 0);
00482     }
00483     for (int y = 0; y <= height + 1 + multiRefIdx; y++)
00484     {
00485       refLeft[y + width] = pSrc.at(y, 1);
00486     }
00487     refMain = bIsModeVer ? refAbove + height : refLeft + width;
00488     refSide = bIsModeVer ? refLeft + width : refAbove + height;
00489 
00490     // Extend the Main reference to the left.
00491     int sizeSide = bIsModeVer ? height : width;
00492     for (int k = -sizeSide; k <= -1; k++)
00493     {
00494       refMain[k] = refSide[std::min((-k * absInvAngle + 256) >> 9, sizeSide)];
00495     }
00496   }
00497   else
00498   {
00499     for (int x = 0; x <= m_topRefLength + multiRefIdx; x++)
00500     {
00501       refAbove[x] = pSrc.at(x, 0);
00502     }
00503     for (int y = 0; y <= m_leftRefLength + multiRefIdx; y++)
00504     {
00505       refLeft[y] = pSrc.at(y, 1);
00506     }
00507 
00508     refMain = bIsModeVer ? refAbove : refLeft;
00509     refSide = bIsModeVer ? refLeft : refAbove;
00510 
00511     // Extend main reference to right using replication
00512     const int log2Ratio = floorLog2(width) - floorLog2(height);
00513     const int s         = std::max<int>(0, bIsModeVer ? log2Ratio : -log2Ratio);
00514     const int maxIndex  = (multiRefIdx << s) + 2;
00515     const int refLength = bIsModeVer ? m_topRefLength : m_leftRefLength;
00516     const Pel val       = refMain[refLength + multiRefIdx];
00517     for (int z = 1; z <= maxIndex; z++)
00518     {
00519       refMain[refLength + multiRefIdx + z] = val;
00520     }
00521   }
00522 
00523   // swap width/height if we are doing a horizontal mode:
00524   if (!bIsModeVer)
00525   {
00526     std::swap(width, height);
00527   }
00528   Pel       tempArray[MAX_CU_SIZE * MAX_CU_SIZE];
00529   const int dstStride = bIsModeVer ? pDst.stride : width;
00530   Pel *     pDstBuf   = bIsModeVer ? pDst.buf : tempArray;
00531 
00532   // compensate for line offset in reference line buffers
00533   refMain += multiRefIdx;
00534   refSide += multiRefIdx;
00535 
00536   Pel *pDsty = pDstBuf;
00537 
00538   if( intraPredAngle == 0 )  // pure vertical or pure horizontal
00539   {
00540     for( int y = 0; y < height; y++ )
00541     {
00542       for( int x = 0; x < width; x++ )
00543       {
00544         pDsty[x] = refMain[x + 1];
00545       }
00546 
00547       if (m_ipaParam.applyPDPC)
00548       {
00549         const int scale   = (floorLog2(width) + floorLog2(height) - 2) >> 2;
00550         const Pel topLeft = refMain[0];
00551         const Pel left    = refSide[1 + y];
00552         for (int x = 0; x < std::min(3 << scale, width); x++)
00553         {
00554           const int wL  = 32 >> (2 * x >> scale);
00555           const Pel val = pDsty[x];
00556           pDsty[x]      = ClipPel(val + ((wL * (left - topLeft) + 32) >> 6), clpRng);
00557         }
00558       }
00559 
00560       pDsty += dstStride;
00561     }
00562   }
00563   else
00564   {
00565     for (int y = 0, deltaPos = intraPredAngle * (1 + multiRefIdx); y<height; y++, deltaPos += intraPredAngle, pDsty += dstStride)
00566     {
00567       const int deltaInt   = deltaPos >> 5;
00568       const int deltaFract = deltaPos & 31;
00569 
00570       if ( !isIntegerSlope( abs(intraPredAngle) ) )
00571       {
00572         if( isLuma(channelType) )
00573         {
00574           const bool useCubicFilter = !m_ipaParam.interpolationFlag;
00575 
00576           const TFilterCoeff        intraSmoothingFilter[4] = {TFilterCoeff(16 - (deltaFract >> 1)), TFilterCoeff(32 - (deltaFract >> 1)), TFilterCoeff(16 + (deltaFract >> 1)), TFilterCoeff(deltaFract >> 1)};
00577           const TFilterCoeff* const f                       = (useCubicFilter) ? InterpolationFilter::getChromaFilterTable(deltaFract) : intraSmoothingFilter;
00578 
00579           for (int x = 0; x < width; x++)
00580           {
00581             Pel p[4];
00582 
00583             p[0] = refMain[deltaInt + x];
00584             p[1] = refMain[deltaInt + x + 1];
00585             p[2] = refMain[deltaInt + x + 2];
00586             p[3] = refMain[deltaInt + x + 3];
00587 
00588             Pel val = (f[0] * p[0] + f[1] * p[1] + f[2] * p[2] + f[3] * p[3] + 32) >> 6;
00589 
00590             pDsty[x] = ClipPel(val, clpRng);   // always clip even though not always needed
00591           }
00592         }
00593         else
00594         {
00595           // Do linear filtering
00596           for (int x = 0; x < width; x++)
00597           {
00598             Pel p[2];
00599 
00600             p[0] = refMain[deltaInt + x + 1];
00601             p[1] = refMain[deltaInt + x + 2];
00602 
00603             pDsty[x] = p[0] + ((deltaFract * (p[1] - p[0]) + 16) >> 5);
00604           }
00605         }
00606       }
00607       else
00608       {
00609         // Just copy the integer samples
00610         for( int x = 0; x < width; x++ )
00611         {
00612           pDsty[x] = refMain[x + deltaInt + 1];
00613         }
00614       }
00615       if (m_ipaParam.applyPDPC)
00616       {
00617         const int scale       = m_ipaParam.angularScale;
00618         int       invAngleSum = 256;
00619 
00620         for (int x = 0; x < std::min(3 << scale, width); x++)
00621         {
00622           invAngleSum += absInvAngle;
00623 
00624           int wL   = 32 >> (2 * x >> scale);
00625           Pel left = refSide[y + (invAngleSum >> 9) + 1];
00626           pDsty[x] = pDsty[x] + ((wL * (left - pDsty[x]) + 32) >> 6);
00627         }
00628       }
00629     }
00630   }
00631 
00632   // Flip the block if this is the horizontal mode
00633   if( !bIsModeVer )
00634   {
00635     for( int y = 0; y < height; y++ )
00636     {
00637       for( int x = 0; x < width; x++ )
00638       {
00639         pDst.at( y, x ) = pDstBuf[x];
00640       }
00641       pDstBuf += dstStride;
00642     }
00643   }
00644 }
00645 
00646 void IntraPrediction::xPredIntraBDPCM(const CPelBuf &pSrc, PelBuf &pDst, const uint32_t dirMode, const ClpRng& clpRng )
00647 {
00648   const int wdt = pDst.width;
00649   const int hgt = pDst.height;
00650 
00651   const int strideP = pDst.stride;
00652   const int strideS = pSrc.stride;
00653 
00654   CHECK( !( dirMode == 1 || dirMode == 2 ), "Incorrect BDPCM mode parameter." );
00655 
00656   Pel* pred = &pDst.buf[0];
00657   if( dirMode == 1 )
00658   {
00659     Pel  val;
00660     for( int y = 0; y < hgt; y++ )
00661     {
00662       val = pSrc.buf[(y + 1) + strideS];
00663       for( int x = 0; x < wdt; x++ )
00664       {
00665         pred[x] = val;
00666       }
00667       pred += strideP;
00668     }
00669   }
00670   else
00671   {
00672     for( int y = 0; y < hgt; y++ )
00673     {
00674       for( int x = 0; x < wdt; x++ )
00675       {
00676         pred[x] = pSrc.buf[x + 1];
00677       }
00678       pred += strideP;
00679     }
00680   }
00681 }
00682 
00683 void IntraPrediction::geneWeightedPred(const ComponentID compId, PelBuf &pred, const PredictionUnit &pu, Pel *srcBuf)
00684 {
00685   const int            width = pred.width;
00686   CHECK(width == 2, "Width of 2 is not supported");
00687   const int            height = pred.height;
00688   const int            srcStride = width;
00689   const int            dstStride = pred.stride;
00690 
00691   Pel*                 dstBuf = pred.buf;
00692   int wIntra, wMerge;
00693 
00694   const Position posBL = pu.Y().bottomLeft();
00695   const Position posTR = pu.Y().topRight();
00696   const PredictionUnit *neigh0 = pu.cs->getPURestricted(posBL.offset(-1, 0), pu, CHANNEL_TYPE_LUMA);
00697   const PredictionUnit *neigh1 = pu.cs->getPURestricted(posTR.offset(0, -1), pu, CHANNEL_TYPE_LUMA);
00698   bool isNeigh0Intra = neigh0 && (CU::isIntra(*neigh0->cu));
00699   bool isNeigh1Intra = neigh1 && (CU::isIntra(*neigh1->cu));
00700 
00701   if (isNeigh0Intra && isNeigh1Intra)
00702   {
00703     wIntra = 3; wMerge = 1;
00704   }
00705   else
00706   {
00707     if (!isNeigh0Intra && !isNeigh1Intra)
00708     {
00709       wIntra = 1; wMerge = 3;
00710     }
00711     else
00712     {
00713       wIntra = 2; wMerge = 2;
00714     }
00715   }
00716   for (int y = 0; y < height; y++)
00717   {
00718     for (int x = 0; x < width; x++)
00719     {
00720       dstBuf[y*dstStride + x] = (wMerge * dstBuf[y*dstStride + x] + wIntra * srcBuf[y*srcStride + x] + 2) >> 2;
00721     }
00722   }
00723 }
00724 
00725 void IntraPrediction::switchBuffer(const PredictionUnit &pu, ComponentID compID, PelBuf srcBuff, Pel *dst)
00726 {
00727   Pel  *src = srcBuff.bufAt(0, 0);
00728   int compWidth = compID == COMPONENT_Y ? pu.Y().width : pu.Cb().width;
00729   int compHeight = compID == COMPONENT_Y ? pu.Y().height : pu.Cb().height;
00730   for (int i = 0; i < compHeight; i++)
00731   {
00732     memcpy(dst, src, compWidth * sizeof(Pel));
00733     src += srcBuff.stride;
00734     dst += compWidth;
00735   }
00736 }
00737 
00738 void IntraPrediction::geneIntrainterPred(const CodingUnit &cu)
00739 {
00740   if (!cu.firstPU->ciipFlag)
00741   {
00742     return;
00743   }
00744 
00745   const PredictionUnit* pu = cu.firstPU;
00746 
00747   initIntraPatternChType(cu, pu->Y());
00748   predIntraAng(COMPONENT_Y, cu.cs->getPredBuf(*pu).Y(), *pu);
00749   int maxCompID = 1;
00750   if (isChromaEnabled(pu->chromaFormat))
00751   {
00752     maxCompID = MAX_NUM_COMPONENT;
00753     if (pu->chromaSize().width > 2)
00754     {
00755       initIntraPatternChType(cu, pu->Cb());
00756       predIntraAng(COMPONENT_Cb, cu.cs->getPredBuf(*pu).Cb(), *pu);
00757 
00758       initIntraPatternChType(cu, pu->Cr());
00759       predIntraAng(COMPONENT_Cr, cu.cs->getPredBuf(*pu).Cr(), *pu);
00760     }
00761   }
00762   for (int currCompID = 0; currCompID < maxCompID; currCompID++)
00763   {
00764     if (currCompID > 0 && pu->chromaSize().width <= 2)
00765     {
00766       continue;
00767     }
00768     ComponentID currCompID2 = (ComponentID)currCompID;
00769     PelBuf tmpBuf = currCompID == 0 ? cu.cs->getPredBuf(*pu).Y() : (currCompID == 1 ? cu.cs->getPredBuf(*pu).Cb() : cu.cs->getPredBuf(*pu).Cr());
00770     switchBuffer(*pu, currCompID2, tmpBuf, getPredictorPtr2(currCompID2, 0));
00771   }
00772 }
00773 
00774 inline bool isAboveLeftAvailable  ( const CodingUnit &cu, const ChannelType &chType, const Position &posLT );
00775 inline int  isAboveAvailable      ( const CodingUnit &cu, const ChannelType &chType, const Position &posLT, const uint32_t uiNumUnitsInPU, const uint32_t unitWidth, bool *validFlags );
00776 inline int  isLeftAvailable       ( const CodingUnit &cu, const ChannelType &chType, const Position &posLT, const uint32_t uiNumUnitsInPU, const uint32_t unitWidth, bool *validFlags );
00777 inline int  isAboveRightAvailable ( const CodingUnit &cu, const ChannelType &chType, const Position &posRT, const uint32_t uiNumUnitsInPU, const uint32_t unitHeight, bool *validFlags );
00778 inline int  isBelowLeftAvailable  ( const CodingUnit &cu, const ChannelType &chType, const Position &posLB, const uint32_t uiNumUnitsInPU, const uint32_t unitHeight, bool *validFlags );
00779 
00780 void IntraPrediction::initIntraPatternChType(const CodingUnit &cu, const CompArea &area, const bool forceRefFilterFlag)
00781 {
00782   CHECK(area.width == 2, "Width of 2 is not supported");
00783   const CodingStructure& cs   = *cu.cs;
00784 
00785   if (!forceRefFilterFlag)
00786   {
00787     initPredIntraParams(*cu.firstPU, area, *cs.sps);
00788   }
00789 
00790   Pel *refBufUnfiltered = m_refBuffer[area.compID][PRED_BUF_UNFILTERED];
00791   Pel *refBufFiltered   = m_refBuffer[area.compID][PRED_BUF_FILTERED];
00792 
00793   setReferenceArrayLengths( area );
00794 
00795   // ----- Step 1: unfiltered reference samples -----
00796   xFillReferenceSamples( cs.picture->getRecoBuf( area ), refBufUnfiltered, area, cu );
00797   // ----- Step 2: filtered reference samples -----
00798   if( m_ipaParam.refFilterFlag || forceRefFilterFlag )
00799   {
00800     xFilterReferenceSamples( refBufUnfiltered, refBufFiltered, area, *cs.sps, cu.firstPU->multiRefIdx );
00801   }
00802 }
00803 
00804 void IntraPrediction::initIntraPatternChTypeISP(const CodingUnit& cu, const CompArea& area, PelBuf& recBuf, const bool forceRefFilterFlag)
00805 {
00806   const CodingStructure& cs = *cu.cs;
00807 
00808   if (!forceRefFilterFlag)
00809   {
00810     initPredIntraParams(*cu.firstPU, area, *cs.sps);
00811   }
00812 
00813   const Position posLT = area;
00814   bool           isLeftAvail  = (cs.getCURestricted(posLT.offset(-1, 0), cu, CHANNEL_TYPE_LUMA) != NULL) && cs.isDecomp(posLT.offset(-1, 0), CHANNEL_TYPE_LUMA);
00815   bool           isAboveAvail = (cs.getCURestricted(posLT.offset(0, -1), cu, CHANNEL_TYPE_LUMA) != NULL) && cs.isDecomp(posLT.offset(0, -1), CHANNEL_TYPE_LUMA);
00816   // ----- Step 1: unfiltered reference samples -----
00817   if (cu.blocks[area.compID].x == area.x && cu.blocks[area.compID].y == area.y)
00818   {
00819     Pel *refBufUnfiltered = m_refBuffer[area.compID][PRED_BUF_UNFILTERED];
00820     // With the first subpartition all the CU reference samples are fetched at once in a single call to xFillReferenceSamples
00821     if (cu.ispMode == HOR_INTRA_SUBPARTITIONS)
00822     {
00823       m_leftRefLength = cu.Y().height << 1;
00824       m_topRefLength = cu.Y().width + area.width;
00825     }
00826     else //if (cu.ispMode == VER_INTRA_SUBPARTITIONS)
00827     {
00828       m_leftRefLength = cu.Y().height + area.height;
00829       m_topRefLength = cu.Y().width << 1;
00830     }
00831 
00832 
00833     xFillReferenceSamples(cs.picture->getRecoBuf(cu.Y()), refBufUnfiltered, cu.Y(), cu);
00834 
00835     // After having retrieved all the CU reference samples, the number of reference samples is now adjusted for the current subpartition
00836     m_topRefLength = cu.blocks[area.compID].width + area.width;
00837     m_leftRefLength = cu.blocks[area.compID].height + area.height;
00838   }
00839   else
00840   {
00841     m_topRefLength = cu.blocks[area.compID].width + area.width;
00842     m_leftRefLength = cu.blocks[area.compID].height + area.height;
00843 
00844     const int predSizeHor = m_topRefLength;
00845     const int predSizeVer = m_leftRefLength;
00846     if (cu.ispMode == HOR_INTRA_SUBPARTITIONS)
00847     {
00848       Pel* src = recBuf.bufAt(0, -1);
00849       Pel *ref = m_refBuffer[area.compID][PRED_BUF_UNFILTERED] + m_refBufferStride[area.compID];
00850       if (isLeftAvail)
00851       {
00852         for (int i = 0; i <= 2 * cu.blocks[area.compID].height - area.height; i++)
00853         {
00854           ref[i] = ref[i + area.height];
00855         }
00856       }
00857       else
00858       {
00859         for (int i = 0; i <= predSizeVer; i++)
00860         {
00861           ref[i] = src[0];
00862         }
00863       }
00864       Pel *dst = m_refBuffer[area.compID][PRED_BUF_UNFILTERED] + 1;
00865       dst[-1]  = ref[0];
00866       for (int i = 0; i < area.width; i++)
00867       {
00868         dst[i] = src[i];
00869       }
00870       Pel sample = src[area.width - 1];
00871       dst += area.width;
00872       for (int i = 0; i < predSizeHor - area.width; i++)
00873       {
00874         dst[i] = sample;
00875       }
00876     }
00877     else
00878     {
00879       Pel* src = recBuf.bufAt(-1, 0);
00880       Pel *ref = m_refBuffer[area.compID][PRED_BUF_UNFILTERED];
00881       if (isAboveAvail)
00882       {
00883         for (int i = 0; i <= 2 * cu.blocks[area.compID].width - area.width; i++)
00884         {
00885           ref[i] = ref[i + area.width];
00886         }
00887       }
00888       else
00889       {
00890         for (int i = 0; i <= predSizeHor; i++)
00891         {
00892           ref[i] = src[0];
00893         }
00894       }
00895       Pel *dst = m_refBuffer[area.compID][PRED_BUF_UNFILTERED] + m_refBufferStride[area.compID] + 1;
00896       dst[-1]  = ref[0];
00897       for (int i = 0; i < area.height; i++)
00898       {
00899         *dst = *src;
00900         src += recBuf.stride;
00901         dst++;
00902       }
00903       Pel sample = src[-recBuf.stride];
00904       for (int i = 0; i < predSizeVer - area.height; i++)
00905       {
00906         *dst = sample;
00907         dst++;
00908       }
00909     }
00910   }
00911   // ----- Step 2: filtered reference samples -----
00912   if (m_ipaParam.refFilterFlag || forceRefFilterFlag)
00913   {
00914     Pel *refBufUnfiltered = m_refBuffer[area.compID][PRED_BUF_UNFILTERED];
00915     Pel *refBufFiltered   = m_refBuffer[area.compID][PRED_BUF_FILTERED];
00916     xFilterReferenceSamples(refBufUnfiltered, refBufFiltered, area, *cs.sps, cu.firstPU->multiRefIdx);
00917   }
00918 }
00919 
00920 
00921 void IntraPrediction::xFillReferenceSamples( const CPelBuf &recoBuf, Pel* refBufUnfiltered, const CompArea &area, const CodingUnit &cu )
00922 {
00923   const ChannelType      chType = toChannelType( area.compID );
00924   const CodingStructure &cs     = *cu.cs;
00925   const SPS             &sps    = *cs.sps;
00926   const PreCalcValues   &pcv    = *cs.pcv;
00927 
00928   const int multiRefIdx         = (area.compID == COMPONENT_Y) ? cu.firstPU->multiRefIdx : 0;
00929 
00930   const int  tuWidth            = area.width;
00931   const int  tuHeight           = area.height;
00932   const int  predSize           = m_topRefLength;
00933   const int  predHSize          = m_leftRefLength;
00934   const int predStride = predSize + 1 + multiRefIdx;
00935   m_refBufferStride[area.compID] = predStride;
00936 
00937   const bool noShift            = pcv.noChroma2x2 && area.width == 4; // don't shift on the lowest level (chroma not-split)
00938   const int  unitWidth          = tuWidth  <= 2 && cu.ispMode && isLuma(area.compID) ? tuWidth  : pcv.minCUWidth  >> (noShift ? 0 : getComponentScaleX(area.compID, sps.getChromaFormatIdc()));
00939   const int  unitHeight         = tuHeight <= 2 && cu.ispMode && isLuma(area.compID) ? tuHeight : pcv.minCUHeight >> (noShift ? 0 : getComponentScaleY(area.compID, sps.getChromaFormatIdc()));
00940 
00941   const int  totalAboveUnits    = (predSize + (unitWidth - 1)) / unitWidth;
00942   const int  totalLeftUnits     = (predHSize + (unitHeight - 1)) / unitHeight;
00943   const int  totalUnits         = totalAboveUnits + totalLeftUnits + 1; //+1 for top-left
00944   const int  numAboveUnits      = std::max<int>( tuWidth / unitWidth, 1 );
00945   const int  numLeftUnits       = std::max<int>( tuHeight / unitHeight, 1 );
00946   const int  numAboveRightUnits = totalAboveUnits - numAboveUnits;
00947   const int  numLeftBelowUnits  = totalLeftUnits - numLeftUnits;
00948 
00949   CHECK( numAboveUnits <= 0 || numLeftUnits <= 0 || numAboveRightUnits <= 0 || numLeftBelowUnits <= 0, "Size not supported" );
00950 
00951   // ----- Step 1: analyze neighborhood -----
00952   const Position posLT          = area;
00953   const Position posRT          = area.topRight();
00954   const Position posLB          = area.bottomLeft();
00955 
00956   bool  neighborFlags[4 * MAX_NUM_PART_IDXS_IN_CTU_WIDTH + 1];
00957   int   numIntraNeighbor = 0;
00958 
00959   memset( neighborFlags, 0, totalUnits );
00960 
00961   neighborFlags[totalLeftUnits] = isAboveLeftAvailable( cu, chType, posLT );
00962   numIntraNeighbor += neighborFlags[totalLeftUnits] ? 1 : 0;
00963   numIntraNeighbor += isAboveAvailable     ( cu, chType, posLT, numAboveUnits,      unitWidth,  (neighborFlags + totalLeftUnits + 1) );
00964   numIntraNeighbor += isAboveRightAvailable( cu, chType, posRT, numAboveRightUnits, unitWidth,  (neighborFlags + totalLeftUnits + 1 + numAboveUnits) );
00965   numIntraNeighbor += isLeftAvailable      ( cu, chType, posLT, numLeftUnits,       unitHeight, (neighborFlags + totalLeftUnits - 1) );
00966   numIntraNeighbor += isBelowLeftAvailable ( cu, chType, posLB, numLeftBelowUnits,  unitHeight, (neighborFlags + totalLeftUnits - 1 - numLeftUnits) );
00967 
00968   // ----- Step 2: fill reference samples (depending on neighborhood) -----
00969 
00970   const Pel*  srcBuf    = recoBuf.buf;
00971   const int   srcStride = recoBuf.stride;
00972         Pel*  ptrDst    = refBufUnfiltered;
00973   const Pel*  ptrSrc;
00974   const Pel   valueDC   = 1 << (sps.getBitDepth( chType ) - 1);
00975 
00976   if( numIntraNeighbor == 0 )
00977   {
00978     // Fill border with DC value
00979     for (int j = 0; j <= predSize + multiRefIdx; j++)
00980     {
00981       ptrDst[j] = valueDC;
00982     }
00983     for (int i = 0; i <= predHSize + multiRefIdx; i++)
00984     {
00985       ptrDst[i + predStride] = valueDC;
00986     }
00987   }
00988   else if( numIntraNeighbor == totalUnits )
00989   {
00990     // Fill top-left border and top and top right with rec. samples
00991     ptrSrc = srcBuf - (1 + multiRefIdx) * srcStride - (1 + multiRefIdx);
00992     for (int j = 0; j <= predSize + multiRefIdx; j++)
00993     {
00994       ptrDst[j] = ptrSrc[j];
00995     }
00996     for (int i = 0; i <= predHSize + multiRefIdx; i++)
00997     {
00998       ptrDst[i + predStride] = ptrSrc[i * srcStride];
00999     }
01000   }
01001   else // reference samples are partially available
01002   {
01003     // Fill top-left sample(s) if available
01004     ptrSrc = srcBuf - (1 + multiRefIdx) * srcStride - (1 + multiRefIdx);
01005     ptrDst = refBufUnfiltered;
01006     if (neighborFlags[totalLeftUnits])
01007     {
01008       ptrDst[0] = ptrSrc[0];
01009       ptrDst[predStride] = ptrSrc[0];
01010       for (int i = 1; i <= multiRefIdx; i++)
01011       {
01012         ptrDst[i] = ptrSrc[i];
01013         ptrDst[i + predStride] = ptrSrc[i * srcStride];
01014       }
01015     }
01016 
01017     // Fill left & below-left samples if available (downwards)
01018     ptrSrc += (1 + multiRefIdx) * srcStride;
01019     ptrDst += (1 + multiRefIdx) + predStride;
01020     for (int unitIdx = totalLeftUnits - 1; unitIdx > 0; unitIdx--)
01021     {
01022       if (neighborFlags[unitIdx])
01023       {
01024         for (int i = 0; i < unitHeight; i++)
01025         {
01026           ptrDst[i] = ptrSrc[i * srcStride];
01027         }
01028       }
01029       ptrSrc += unitHeight * srcStride;
01030       ptrDst += unitHeight;
01031     }
01032     // Fill last below-left sample(s)
01033     if (neighborFlags[0])
01034     {
01035       int lastSample = (predHSize % unitHeight == 0) ? unitHeight : predHSize % unitHeight;
01036       for (int i = 0; i < lastSample; i++)
01037       {
01038         ptrDst[i] = ptrSrc[i * srcStride];
01039       }
01040     }
01041 
01042     // Fill above & above-right samples if available (left-to-right)
01043     ptrSrc = srcBuf - srcStride * (1 + multiRefIdx);
01044     ptrDst = refBufUnfiltered + 1 + multiRefIdx;
01045     for (int unitIdx = totalLeftUnits + 1; unitIdx < totalUnits - 1; unitIdx++)
01046     {
01047       if (neighborFlags[unitIdx])
01048       {
01049         for (int j = 0; j < unitWidth; j++)
01050         {
01051           ptrDst[j] = ptrSrc[j];
01052         }
01053       }
01054       ptrSrc += unitWidth;
01055       ptrDst += unitWidth;
01056     }
01057     // Fill last above-right sample(s)
01058     if (neighborFlags[totalUnits - 1])
01059     {
01060       int lastSample = (predSize % unitWidth == 0) ? unitWidth : predSize % unitWidth;
01061       for (int j = 0; j < lastSample; j++)
01062       {
01063         ptrDst[j] = ptrSrc[j];
01064       }
01065     }
01066 
01067     // pad from first available down to the last below-left
01068     ptrDst = refBufUnfiltered;
01069     int lastAvailUnit = 0;
01070     if (!neighborFlags[0])
01071     {
01072       int firstAvailUnit = 1;
01073       while (firstAvailUnit < totalUnits && !neighborFlags[firstAvailUnit])
01074       {
01075         firstAvailUnit++;
01076       }
01077 
01078       // first available sample
01079       int firstAvailRow = -1;
01080       int firstAvailCol = 0;
01081       if (firstAvailUnit < totalLeftUnits)
01082       {
01083         firstAvailRow = (totalLeftUnits - firstAvailUnit) * unitHeight + multiRefIdx;
01084       }
01085       else if (firstAvailUnit == totalLeftUnits)
01086       {
01087         firstAvailRow = multiRefIdx;
01088       }
01089       else
01090       {
01091         firstAvailCol = (firstAvailUnit - totalLeftUnits - 1) * unitWidth + 1 + multiRefIdx;
01092       }
01093       const Pel firstAvailSample = ptrDst[firstAvailRow < 0 ? firstAvailCol : firstAvailRow + predStride];
01094 
01095       // last sample below-left (n.a.)
01096       int lastRow = predHSize + multiRefIdx;
01097 
01098       // fill left column
01099       for (int i = lastRow; i > firstAvailRow; i--)
01100       {
01101         ptrDst[i + predStride] = firstAvailSample;
01102       }
01103       // fill top row
01104       if (firstAvailCol > 0)
01105       {
01106         for (int j = 0; j < firstAvailCol; j++)
01107         {
01108           ptrDst[j] = firstAvailSample;
01109         }
01110       }
01111       lastAvailUnit = firstAvailUnit;
01112     }
01113 
01114     // pad all other reference samples.
01115     int currUnit = lastAvailUnit + 1;
01116     while (currUnit < totalUnits)
01117     {
01118       if (!neighborFlags[currUnit]) // samples not available
01119       {
01120         // last available sample
01121         int lastAvailRow = -1;
01122         int lastAvailCol = 0;
01123         if (lastAvailUnit < totalLeftUnits)
01124         {
01125           lastAvailRow = (totalLeftUnits - lastAvailUnit - 1) * unitHeight + multiRefIdx + 1;
01126         }
01127         else if (lastAvailUnit == totalLeftUnits)
01128         {
01129           lastAvailCol = multiRefIdx;
01130         }
01131         else
01132         {
01133           lastAvailCol = (lastAvailUnit - totalLeftUnits) * unitWidth + multiRefIdx;
01134         }
01135         const Pel lastAvailSample = ptrDst[lastAvailRow < 0 ? lastAvailCol : lastAvailRow + predStride];
01136 
01137         // fill current unit with last available sample
01138         if (currUnit < totalLeftUnits)
01139         {
01140           for (int i = lastAvailRow - 1; i >= lastAvailRow - unitHeight; i--)
01141           {
01142             ptrDst[i + predStride] = lastAvailSample;
01143           }
01144         }
01145         else if (currUnit == totalLeftUnits)
01146         {
01147           for (int i = 0; i < multiRefIdx + 1; i++)
01148           {
01149             ptrDst[i + predStride] = lastAvailSample;
01150           }
01151           for (int j = 0; j < multiRefIdx + 1; j++)
01152           {
01153             ptrDst[j] = lastAvailSample;
01154           }
01155         }
01156         else
01157         {
01158           int numSamplesInUnit = (currUnit == totalUnits - 1) ? ((predSize % unitWidth == 0) ? unitWidth : predSize % unitWidth) : unitWidth;
01159           for (int j = lastAvailCol + 1; j <= lastAvailCol + numSamplesInUnit; j++)
01160           {
01161             ptrDst[j] = lastAvailSample;
01162           }
01163         }
01164       }
01165       lastAvailUnit = currUnit;
01166       currUnit++;
01167     }
01168   }
01169 }
01170 
01171 void IntraPrediction::xFilterReferenceSamples(const Pel *refBufUnfiltered, Pel *refBufFiltered, const CompArea &area,
01172                                               const SPS &sps, int multiRefIdx)
01173 {
01174   if (area.compID != COMPONENT_Y)
01175   {
01176     multiRefIdx = 0;
01177   }
01178   const int predSize = m_topRefLength + multiRefIdx;
01179   const int predHSize = m_leftRefLength + multiRefIdx;
01180   const size_t predStride = m_refBufferStride[area.compID];
01181 
01182   const Pel topLeft =
01183     (refBufUnfiltered[0] + refBufUnfiltered[1] + refBufUnfiltered[predStride] + refBufUnfiltered[predStride + 1] + 2)
01184     >> 2;
01185 
01186   refBufFiltered[0] = topLeft;
01187 
01188   for (int i = 1; i < predSize; i++)
01189   {
01190     refBufFiltered[i] = (refBufUnfiltered[i - 1] + 2 * refBufUnfiltered[i] + refBufUnfiltered[i + 1] + 2) >> 2;
01191   }
01192   refBufFiltered[predSize] = refBufUnfiltered[predSize];
01193 
01194   refBufFiltered += predStride;
01195   refBufUnfiltered += predStride;
01196 
01197   refBufFiltered[0] = topLeft;
01198 
01199   for (int i = 1; i < predHSize; i++)
01200   {
01201     refBufFiltered[i] = (refBufUnfiltered[i - 1] + 2 * refBufUnfiltered[i] + refBufUnfiltered[i + 1] + 2) >> 2;
01202   }
01203   refBufFiltered[predHSize] = refBufUnfiltered[predHSize];
01204 }
