01206 bool isAboveLeftAvailable(const CodingUnit &cu, const ChannelType &chType, const Position &posLT)
01207 {
01208   const CodingStructure& cs = *cu.cs;
01209   const Position refPos = posLT.offset(-1, -1);
01210 
01211   if (!cs.isDecomp(refPos, chType))
01212   {
01213     return false;
01214   }
01215 
01216   return (cs.getCURestricted(refPos, cu, chType) != NULL);
01217 }
01218 
01219 int isAboveAvailable(const CodingUnit &cu, const ChannelType &chType, const Position &posLT, const uint32_t uiNumUnitsInPU, const uint32_t unitWidth, bool *bValidFlags)
01220 {
01221   const CodingStructure& cs = *cu.cs;
01222 
01223   bool *    validFlags = bValidFlags;
01224   int       numIntra   = 0;
01225   const int maxDx      = uiNumUnitsInPU * unitWidth;
01226 
01227   for (int dx = 0; dx < maxDx; dx += unitWidth)
01228   {
01229     const Position refPos = posLT.offset(dx, -1);
01230 
01231     if (!cs.isDecomp(refPos, chType))
01232     {
01233       break;
01234     }
01235 
01236     const bool valid = (cs.getCURestricted(refPos, cu, chType) != NULL);
01237     numIntra += valid ? 1 : 0;
01238     *validFlags = valid;
01239 
01240     validFlags++;
01241   }
01242 
01243   return numIntra;
01244 }
