01327 // LumaRecPixels
01328 void IntraPrediction::xGetLumaRecPixels(const PredictionUnit &pu, CompArea chromaArea)
01329 {
01330   int iDstStride = 0;
01331   Pel* pDst0 = 0;
01332   int curChromaMode = pu.intraDir[1];
01333   if ((curChromaMode == MDLM_L_IDX) || (curChromaMode == MDLM_T_IDX))
01334   {
01335     iDstStride = 2 * MAX_CU_SIZE + 1;
01336     pDst0 = m_pMdlmTemp + iDstStride + 1;
01337   }
01338   else
01339   {
01340     iDstStride = MAX_CU_SIZE + 1;
01341     pDst0 = m_piTemp + iDstStride + 1; //MMLM_SAMPLE_NEIGHBOR_LINES;
01342   }
01343   //assert 420 chroma subsampling
01344   CompArea lumaArea = CompArea( COMPONENT_Y, pu.chromaFormat, chromaArea.lumaPos(), recalcSize( pu.chromaFormat, CHANNEL_TYPE_CHROMA, CHANNEL_TYPE_LUMA, chromaArea.size() ) );//needed for correct pos/size (4x4 Tus)
01345 
01346   CHECK(lumaArea.width == chromaArea.width && CHROMA_444 != pu.chromaFormat, "");
01347   CHECK(lumaArea.height == chromaArea.height && CHROMA_444 != pu.chromaFormat && CHROMA_422 != pu.chromaFormat, "");
01348 
01349   const SizeType uiCWidth = chromaArea.width;
01350   const SizeType uiCHeight = chromaArea.height;
01351 
01352   const CPelBuf Src = pu.cs->picture->getRecoBuf( lumaArea );
01353   Pel const* pRecSrc0   = Src.bufAt( 0, 0 );
01354   int iRecStride        = Src.stride;
01355   int logSubWidthC  = getChannelTypeScaleX(CHANNEL_TYPE_CHROMA, pu.chromaFormat);
01356   int logSubHeightC = getChannelTypeScaleY(CHANNEL_TYPE_CHROMA, pu.chromaFormat);
01357 
01358   int iRecStride2       = iRecStride << logSubHeightC;
01359 
01360   const CodingUnit& lumaCU = isChroma( pu.chType ) ? *pu.cs->picture->cs->getCU( lumaArea.pos(), CH_L ) : *pu.cu;
01361   const CodingUnit&     cu = *pu.cu;
01362 
01363   const CompArea& area = isChroma( pu.chType ) ? chromaArea : lumaArea;
01364 
01365   const uint32_t uiTuWidth  = area.width;
01366   const uint32_t uiTuHeight = area.height;
01367 
01368   int iBaseUnitSize = ( 1 << MIN_CU_LOG2 );
01369 
01370   const int  iUnitWidth       = iBaseUnitSize >> getComponentScaleX( area.compID, area.chromaFormat );
01371   const int  iUnitHeight = iBaseUnitSize >> getComponentScaleY(area.compID, area.chromaFormat);
01372 
01373   const int  iTUWidthInUnits = uiTuWidth / iUnitWidth;
01374   const int  iTUHeightInUnits = uiTuHeight / iUnitHeight;
01375   const int  iAboveUnits      = iTUWidthInUnits;
01376   const int  iLeftUnits       = iTUHeightInUnits;
01377   const int  chromaUnitWidth = iBaseUnitSize >> getComponentScaleX(COMPONENT_Cb, area.chromaFormat);
01378   const int  chromaUnitHeight = iBaseUnitSize >> getComponentScaleY(COMPONENT_Cb, area.chromaFormat);
01379   const int  topTemplateSampNum = 2 * uiCWidth; // for MDLM, the number of template samples is 2W or 2H.
01380   const int  leftTemplateSampNum = 2 * uiCHeight;
01381   assert(m_topRefLength >= topTemplateSampNum);
01382   assert(m_leftRefLength >= leftTemplateSampNum);
01383   const int  totalAboveUnits = (topTemplateSampNum + (chromaUnitWidth - 1)) / chromaUnitWidth;
01384   const int  totalLeftUnits = (leftTemplateSampNum + (chromaUnitHeight - 1)) / chromaUnitHeight;
01385   const int  totalUnits = totalLeftUnits + totalAboveUnits + 1;
01386   const int  aboveRightUnits = totalAboveUnits - iAboveUnits;
01387   const int  leftBelowUnits = totalLeftUnits - iLeftUnits;
01388 
01389   int avaiAboveRightUnits = 0;
01390   int avaiLeftBelowUnits = 0;
01391   bool  bNeighborFlags[4 * MAX_NUM_PART_IDXS_IN_CTU_WIDTH + 1];
01392   memset(bNeighborFlags, 0, totalUnits);
01393   bool aboveIsAvailable, leftIsAvailable;
01394 
01395   int availlableUnit = isLeftAvailable(isChroma(pu.chType) ? cu : lumaCU, toChannelType(area.compID), area.pos(),
01396                                        iLeftUnits, iUnitHeight, (bNeighborFlags + iLeftUnits + leftBelowUnits - 1));
01397 
01398   leftIsAvailable = availlableUnit == iTUHeightInUnits;
01399 
01400   availlableUnit = isAboveAvailable(isChroma(pu.chType) ? cu : lumaCU, toChannelType(area.compID), area.pos(),
01401                                     iAboveUnits, iUnitWidth, (bNeighborFlags + iLeftUnits + leftBelowUnits + 1));
01402 
01403   aboveIsAvailable = availlableUnit == iTUWidthInUnits;
01404 
01405   if (leftIsAvailable)   // if left is not available, then the below left is not available
01406   {
01407     avaiLeftBelowUnits = isBelowLeftAvailable(isChroma(pu.chType) ? cu : lumaCU, toChannelType(area.compID), area.bottomLeftComp(area.compID), leftBelowUnits, iUnitHeight, (bNeighborFlags + leftBelowUnits - 1));
01408   }
01409 
01410   if (aboveIsAvailable)   // if above is not available, then  the above right is not available.
01411   {
01412     avaiAboveRightUnits = isAboveRightAvailable(isChroma(pu.chType) ? cu : lumaCU, toChannelType(area.compID), area.topRightComp(area.compID), aboveRightUnits, iUnitWidth, (bNeighborFlags + iLeftUnits + leftBelowUnits + iAboveUnits + 1));
01413   }
01414 
01415   Pel*       pDst  = nullptr;
01416   Pel const* piSrc = nullptr;
01417 
01418   bool isFirstRowOfCtu = (lumaArea.y & ((pu.cs->sps)->getCTUSize() - 1)) == 0;
01419 
01420   if (aboveIsAvailable)
01421   {
01422     pDst  = pDst0    - iDstStride;
01423     int addedAboveRight = 0;
01424     if ((curChromaMode == MDLM_L_IDX) || (curChromaMode == MDLM_T_IDX))
01425     {
01426       addedAboveRight = avaiAboveRightUnits*chromaUnitWidth;
01427     }
01428     for (int i = 0; i < uiCWidth + addedAboveRight; i++)
01429     {
01430       const bool leftPadding = i == 0 && !leftIsAvailable;
01431       if (pu.chromaFormat == CHROMA_444)
01432       {
01433         piSrc = pRecSrc0 - iRecStride;
01434         pDst[i] = piSrc[i];
01435       }
01436       else if (isFirstRowOfCtu)
01437       {
01438         piSrc   = pRecSrc0 - iRecStride;
01439         pDst[i] = (piSrc[2 * i] * 2 + piSrc[2 * i - (leftPadding ? 0 : 1)] + piSrc[2 * i + 1] + 2) >> 2;
01440       }
01441       else if (pu.chromaFormat == CHROMA_422)
01442       {
01443         piSrc = pRecSrc0 - iRecStride2;
01444 
01445         int s = 2;
01446         s += piSrc[2 * i] * 2;
01447         s += piSrc[2 * i - (leftPadding ? 0 : 1)];
01448         s += piSrc[2 * i + 1];
01449         pDst[i] = s >> 2;
01450       }
01451       else if (pu.cs->sps->getCclmCollocatedChromaFlag())
01452       {
01453         piSrc = pRecSrc0 - iRecStride2;
01454 
01455         int s = 4;
01456         s += piSrc[2 * i - iRecStride];
01457         s += piSrc[2 * i] * 4;
01458         s += piSrc[2 * i - (leftPadding ? 0 : 1)];
01459         s += piSrc[2 * i + 1];
01460         s += piSrc[2 * i + iRecStride];
01461         pDst[i] = s >> 3;
01462       }
01463       else
01464       {
01465         piSrc = pRecSrc0 - iRecStride2;
01466         int s = 4;
01467         s += piSrc[2 * i] * 2;
01468         s += piSrc[2 * i + 1];
01469         s += piSrc[2 * i - (leftPadding ? 0 : 1)];
01470         s += piSrc[2 * i + iRecStride] * 2;
01471         s += piSrc[2 * i + 1 + iRecStride];
01472         s += piSrc[2 * i + iRecStride - (leftPadding ? 0 : 1)];
01473         pDst[i] = s >> 3;
01474       }
01475     }
01476   }
01477 
01478   if (leftIsAvailable)
01479   {
01480     pDst  = pDst0    - 1;
01481     piSrc = pRecSrc0 - 1 - logSubWidthC;
01482 
01483     int addedLeftBelow = 0;
01484     if ((curChromaMode == MDLM_L_IDX) || (curChromaMode == MDLM_T_IDX))
01485     {
01486       addedLeftBelow = avaiLeftBelowUnits*chromaUnitHeight;
01487     }
01488 
01489     for (int j = 0; j < uiCHeight + addedLeftBelow; j++)
01490     {
01491       if (pu.chromaFormat == CHROMA_444)
01492       {
01493         pDst[0] = piSrc[0];
01494       }
01495       else if (pu.chromaFormat == CHROMA_422)
01496       {
01497         int s = 2;
01498         s += piSrc[0] * 2;
01499         s += piSrc[-1];
01500         s += piSrc[1];
01501         pDst[0] = s >> 2;
01502       }
01503       else if (pu.cs->sps->getCclmCollocatedChromaFlag())
01504       {
01505         const bool abovePadding = j == 0 && !aboveIsAvailable;
01506 
01507         int s = 4;
01508         s += piSrc[-(abovePadding ? 0 : iRecStride)];
01509         s += piSrc[0] * 4;
01510         s += piSrc[-1];
01511         s += piSrc[1];
01512         s += piSrc[iRecStride];
01513         pDst[0] = s >> 3;
01514       }
01515       else
01516       {
01517         int s = 4;
01518         s += piSrc[0] * 2;
01519         s += piSrc[1];
01520         s += piSrc[-1];
01521         s += piSrc[iRecStride] * 2;
01522         s += piSrc[iRecStride + 1];
01523         s += piSrc[iRecStride - 1];
01524         pDst[0] = s >> 3;
01525       }
01526 
01527       piSrc += iRecStride2;
01528       pDst  += iDstStride;
01529     }
01530   }
01531 
01532   // inner part from reconstructed picture buffer
01533   for( int j = 0; j < uiCHeight; j++ )
01534   {
01535     for( int i = 0; i < uiCWidth; i++ )
01536     {
01537       if (pu.chromaFormat == CHROMA_444)
01538       {
01539         pDst0[i] = pRecSrc0[i];
01540       }
01541       else if (pu.chromaFormat == CHROMA_422)
01542       {
01543         const bool leftPadding  = i == 0 && !leftIsAvailable;
01544 
01545         int s = 2;
01546         s += pRecSrc0[2 * i] * 2;
01547         s += pRecSrc0[2 * i - (leftPadding ? 0 : 1)];
01548         s += pRecSrc0[2 * i + 1];
01549         pDst0[i] = s >> 2;
01550       }
01551       else if (pu.cs->sps->getCclmCollocatedChromaFlag())
01552       {
01553         const bool leftPadding  = i == 0 && !leftIsAvailable;
01554         const bool abovePadding = j == 0 && !aboveIsAvailable;
01555 
01556         int s = 4;
01557         s += pRecSrc0[2 * i - (abovePadding ? 0 : iRecStride)];
01558         s += pRecSrc0[2 * i] * 4;
01559         s += pRecSrc0[2 * i - (leftPadding ? 0 : 1)];
01560         s += pRecSrc0[2 * i + 1];
01561         s += pRecSrc0[2 * i + iRecStride];
01562         pDst0[i] = s >> 3;
01563       }
01564       else
01565       {
01566         CHECK(pu.chromaFormat != CHROMA_420, "Chroma format must be 4:2:0 for vertical filtering");
01567         const bool leftPadding = i == 0 && !leftIsAvailable;
01568 
01569         int s = 4;
01570         s += pRecSrc0[2 * i] * 2;
01571         s += pRecSrc0[2 * i + 1];
01572         s += pRecSrc0[2 * i - (leftPadding ? 0 : 1)];
01573         s += pRecSrc0[2 * i + iRecStride] * 2;
01574         s += pRecSrc0[2 * i + 1 + iRecStride];
01575         s += pRecSrc0[2 * i + iRecStride - (leftPadding ? 0 : 1)];
01576         pDst0[i] = s >> 3;
01577       }
01578     }
01579 
01580     pDst0    += iDstStride;
01581     pRecSrc0 += iRecStride2;
01582   }
01583 }
01584 void IntraPrediction::xGetLMParameters(const PredictionUnit &pu, const ComponentID compID,
01585                                               const CompArea &chromaArea,
01586                                               int &a, int &b, int &iShift)
01587 {
01588   CHECK(compID == COMPONENT_Y, "");
01589 
01590   const SizeType cWidth  = chromaArea.width;
01591   const SizeType cHeight = chromaArea.height;
01592 
01593   const Position posLT = chromaArea;
01594 
01595   CodingStructure & cs = *(pu.cs);
01596   const CodingUnit &cu = *(pu.cu);
01597 
01598   const SPS &        sps           = *cs.sps;
01599   const uint32_t     tuWidth     = chromaArea.width;
01600   const uint32_t     tuHeight    = chromaArea.height;
01601   const ChromaFormat nChromaFormat = sps.getChromaFormatIdc();
01602 
01603   const int baseUnitSize = 1 << MIN_CU_LOG2;
01604   const int unitWidth    = baseUnitSize >> getComponentScaleX(chromaArea.compID, nChromaFormat);
01605   const int unitHeight   = baseUnitSize >> getComponentScaleY(chromaArea.compID, nChromaFormat);
01606 
01607   const int tuWidthInUnits  = tuWidth / unitWidth;
01608   const int tuHeightInUnits = tuHeight / unitHeight;
01609   const int aboveUnits      = tuWidthInUnits;
01610   const int leftUnits       = tuHeightInUnits;
01611   int topTemplateSampNum = 2 * cWidth; // for MDLM, the template sample number is 2W or 2H;
01612   int leftTemplateSampNum = 2 * cHeight;
01613   assert(m_topRefLength >= topTemplateSampNum);
01614   assert(m_leftRefLength >= leftTemplateSampNum);
01615   int totalAboveUnits = (topTemplateSampNum + (unitWidth - 1)) / unitWidth;
01616   int totalLeftUnits = (leftTemplateSampNum + (unitHeight - 1)) / unitHeight;
01617   int totalUnits = totalLeftUnits + totalAboveUnits + 1;
01618   int aboveRightUnits = totalAboveUnits - aboveUnits;
01619   int leftBelowUnits = totalLeftUnits - leftUnits;
01620   int avaiAboveRightUnits = 0;
01621   int avaiLeftBelowUnits = 0;
01622   int avaiAboveUnits = 0;
01623   int avaiLeftUnits = 0;
01624 
01625   int curChromaMode = pu.intraDir[1];
01626   bool neighborFlags[4 * MAX_NUM_PART_IDXS_IN_CTU_WIDTH + 1];
01627   memset(neighborFlags, 0, totalUnits);
01628 
01629   bool aboveAvailable, leftAvailable;
01630 
01631   int availableUnit =
01632     isAboveAvailable(cu, CHANNEL_TYPE_CHROMA, posLT, aboveUnits, unitWidth,
01633     (neighborFlags + leftUnits + leftBelowUnits + 1));
01634   aboveAvailable = availableUnit == tuWidthInUnits;
01635 
01636   availableUnit =
01637     isLeftAvailable(cu, CHANNEL_TYPE_CHROMA, posLT, leftUnits, unitHeight,
01638     (neighborFlags + leftUnits + leftBelowUnits - 1));
01639   leftAvailable = availableUnit == tuHeightInUnits;
01640   if (leftAvailable) // if left is not available, then the below left is not available
01641   {
01642     avaiLeftUnits = tuHeightInUnits;
01643     avaiLeftBelowUnits = isBelowLeftAvailable(cu, CHANNEL_TYPE_CHROMA, chromaArea.bottomLeftComp(chromaArea.compID), leftBelowUnits, unitHeight, (neighborFlags + leftBelowUnits - 1));
01644   }
01645   if (aboveAvailable) // if above is not available, then  the above right is not available.
01646   {
01647     avaiAboveUnits = tuWidthInUnits;
01648     avaiAboveRightUnits = isAboveRightAvailable(cu, CHANNEL_TYPE_CHROMA, chromaArea.topRightComp(chromaArea.compID), aboveRightUnits, unitWidth, (neighborFlags + leftUnits + leftBelowUnits + aboveUnits + 1));
01649   }
01650   Pel *srcColor0, *curChroma0;
01651   int srcStride;
01652 
01653   PelBuf temp;
01654   if ((curChromaMode == MDLM_L_IDX) || (curChromaMode == MDLM_T_IDX))
01655   {
01656     srcStride = 2 * MAX_CU_SIZE + 1;
01657     temp = PelBuf(m_pMdlmTemp + srcStride + 1, srcStride, Size(chromaArea));
01658   }
01659   else
01660   {
01661     srcStride = MAX_CU_SIZE + 1;
01662     temp        = PelBuf(m_piTemp + srcStride + 1, srcStride, Size(chromaArea));
01663   }
01664   srcColor0 = temp.bufAt(0, 0);
01665   curChroma0 = getPredictorPtr(compID);
01666 
01667   unsigned internalBitDepth = sps.getBitDepth(CHANNEL_TYPE_CHROMA);
01668 
01669   int minLuma[2] = {  MAX_INT, 0 };
01670   int maxLuma[2] = { -MAX_INT, 0 };
01671 
01672   Pel *src = srcColor0 - srcStride;
01673   int actualTopTemplateSampNum = 0;
01674   int actualLeftTemplateSampNum = 0;
01675   if (curChromaMode == MDLM_T_IDX)
01676   {
01677     leftAvailable = 0;
01678     avaiAboveRightUnits = avaiAboveRightUnits > (cHeight/unitWidth) ?  cHeight/unitWidth : avaiAboveRightUnits;
01679     actualTopTemplateSampNum = unitWidth*(avaiAboveUnits + avaiAboveRightUnits);
01680   }
01681   else if (curChromaMode == MDLM_L_IDX)
01682   {
01683     aboveAvailable = 0;
01684     avaiLeftBelowUnits = avaiLeftBelowUnits > (cWidth/unitHeight) ? cWidth/unitHeight : avaiLeftBelowUnits;
01685     actualLeftTemplateSampNum = unitHeight*(avaiLeftUnits + avaiLeftBelowUnits);
01686   }
01687   else if (curChromaMode == LM_CHROMA_IDX)
01688   {
01689     actualTopTemplateSampNum = cWidth;
01690     actualLeftTemplateSampNum = cHeight;
01691   }
01692   int startPos[2]; //0:Above, 1: Left
01693   int pickStep[2];
01694 
01695   int aboveIs4 = leftAvailable  ? 0 : 1;
01696   int leftIs4 =  aboveAvailable ? 0 : 1;
01697 
01698   startPos[0] = actualTopTemplateSampNum >> (2 + aboveIs4);
01699   pickStep[0] = std::max(1, actualTopTemplateSampNum >> (1 + aboveIs4));
01700 
01701   startPos[1] = actualLeftTemplateSampNum >> (2 + leftIs4);
01702   pickStep[1] = std::max(1, actualLeftTemplateSampNum >> (1 + leftIs4));
01703 
01704   Pel selectLumaPix[4] = { 0, 0, 0, 0 };
01705   Pel selectChromaPix[4] = { 0, 0, 0, 0 };
01706 
01707   int cntT, cntL;
01708   cntT = cntL = 0;
01709   int cnt = 0;
01710   if (aboveAvailable)
01711   {
01712     cntT = std::min(actualTopTemplateSampNum, (1 + aboveIs4) << 1);
01713     src = srcColor0 - srcStride;
01714     const Pel *cur = curChroma0 + 1;
01715     for (int pos = startPos[0]; cnt < cntT; pos += pickStep[0], cnt++)
01716     {
01717       selectLumaPix[cnt] = src[pos];
01718       selectChromaPix[cnt] = cur[pos];
01719     }
01720   }
01721 
01722   if (leftAvailable)
01723   {
01724     cntL = std::min(actualLeftTemplateSampNum, ( 1 + leftIs4 ) << 1 );
01725     src = srcColor0 - 1;
01726     const Pel *cur = curChroma0 + m_refBufferStride[compID] + 1;
01727     for (int pos = startPos[1], cnt = 0; cnt < cntL; pos += pickStep[1], cnt++)
01728     {
01729       selectLumaPix[cnt + cntT] = src[pos * srcStride];
01730       selectChromaPix[cnt + cntT] = cur[pos];
01731     }
01732   }
01733   cnt = cntL + cntT;
01734 
01735   if (cnt == 2)
01736   {
01737     selectLumaPix[3] = selectLumaPix[0]; selectChromaPix[3] = selectChromaPix[0];
01738     selectLumaPix[2] = selectLumaPix[1]; selectChromaPix[2] = selectChromaPix[1];
01739     selectLumaPix[0] = selectLumaPix[1]; selectChromaPix[0] = selectChromaPix[1];
01740     selectLumaPix[1] = selectLumaPix[3]; selectChromaPix[1] = selectChromaPix[3];
01741   }
01742 
01743   int minGrpIdx[2] = { 0, 2 };
01744   int maxGrpIdx[2] = { 1, 3 };
01745   int *tmpMinGrp = minGrpIdx;
01746   int *tmpMaxGrp = maxGrpIdx;
01747   if (selectLumaPix[tmpMinGrp[0]] > selectLumaPix[tmpMinGrp[1]])
01748   {
01749     std::swap(tmpMinGrp[0], tmpMinGrp[1]);
01750   }
01751   if (selectLumaPix[tmpMaxGrp[0]] > selectLumaPix[tmpMaxGrp[1]])
01752   {
01753     std::swap(tmpMaxGrp[0], tmpMaxGrp[1]);
01754   }
01755   if (selectLumaPix[tmpMinGrp[0]] > selectLumaPix[tmpMaxGrp[1]])
01756   {
01757     std::swap(tmpMinGrp, tmpMaxGrp);
01758   }
01759   if (selectLumaPix[tmpMinGrp[1]] > selectLumaPix[tmpMaxGrp[0]])
01760   {
01761     std::swap(tmpMinGrp[1], tmpMaxGrp[0]);
01762   }
01763 
01764   minLuma[0] = (selectLumaPix[tmpMinGrp[0]] + selectLumaPix[tmpMinGrp[1]] + 1 )>>1;
01765   minLuma[1] = (selectChromaPix[tmpMinGrp[0]] + selectChromaPix[tmpMinGrp[1]] + 1) >> 1;
01766   maxLuma[0] = (selectLumaPix[tmpMaxGrp[0]] + selectLumaPix[tmpMaxGrp[1]] + 1 )>>1;
01767   maxLuma[1] = (selectChromaPix[tmpMaxGrp[0]] + selectChromaPix[tmpMaxGrp[1]] + 1) >> 1;
01768 
01769   if (leftAvailable || aboveAvailable)
01770   {
01771     int diff = maxLuma[0] - minLuma[0];
01772     if (diff > 0)
01773     {
01774       int diffC = maxLuma[1] - minLuma[1];
01775       int x = floorLog2( diff );
01776       static const uint8_t DivSigTable[1 << 4] = {
01777         // 4bit significands - 8 ( MSB is omitted )
01778         0,  7,  6,  5,  5,  4,  4,  3,  3,  2,  2,  1,  1,  1,  1,  0
01779       };
01780       int normDiff = (diff << 4 >> x) & 15;
01781       int v = DivSigTable[normDiff] | 8;
01782       x += normDiff != 0;
01783 
01784       int y = floorLog2( abs( diffC ) ) + 1;
01785       int add = 1 << y >> 1;
01786       a = (diffC * v + add) >> y;
01787       iShift = 3 + x - y;
01788       if ( iShift < 1 )
01789       {
01790         iShift = 1;
01791         a = ( (a == 0)? 0: (a < 0)? -15 : 15 );   // a=Sign(a)*15
01792       }
01793       b = minLuma[1] - ((a * minLuma[0]) >> iShift);
01794     }
01795     else
01796     {
01797       a = 0;
01798       b = minLuma[1];
01799       iShift = 0;
01800     }
01801   }
01802   else
01803   {
01804     a = 0;
01805 
01806     b = 1 << (internalBitDepth - 1);
01807 
01808     iShift = 0;
01809   }
01810 }
01811 
01812 void IntraPrediction::initIntraMip( const PredictionUnit &pu, const CompArea &area )
01813 {
01814   CHECK( area.width > MIP_MAX_WIDTH || area.height > MIP_MAX_HEIGHT, "Error: block size not supported for MIP" );
01815 
01816   // prepare input (boundary) data for prediction
01817   CHECK( m_ipaParam.refFilterFlag, "ERROR: unfiltered refs expected for MIP" );
01818   Pel       *ptrSrc     = getPredictorPtr(area.compID);
01819   const int  srcStride  = m_refBufferStride[area.compID];
01820   const int  srcHStride = 2;
01821 
01822   m_matrixIntraPred.prepareInputForPred(CPelBuf(ptrSrc, srcStride, srcHStride), area,
01823                                         pu.cu->slice->getSPS()->getBitDepth(toChannelType(area.compID)), area.compID);
01824 }
01825 
01826 void IntraPrediction::predIntraMip( const ComponentID compId, PelBuf &piPred, const PredictionUnit &pu )
01827 {
01828   CHECK( piPred.width > MIP_MAX_WIDTH || piPred.height > MIP_MAX_HEIGHT, "Error: block size not supported for MIP" );
01829   CHECK( piPred.width != (1 << floorLog2(piPred.width)) || piPred.height != (1 << floorLog2(piPred.height)), "Error: expecting blocks of size 2^M x 2^N" );
01830 
01831   // generate mode-specific prediction
01832   uint32_t modeIdx       = MAX_NUM_MIP_MODE;
01833   bool     transposeFlag = false;
01834   if (compId == COMPONENT_Y)
01835   {
01836     modeIdx       = pu.intraDir[CHANNEL_TYPE_LUMA];
01837     transposeFlag = pu.mipTransposedFlag;
01838   }
01839   else
01840   {
01841     const PredictionUnit &coLocatedLumaPU = PU::getCoLocatedLumaPU(pu);
01842 
01843     CHECK(pu.intraDir[CHANNEL_TYPE_CHROMA] != DM_CHROMA_IDX, "Error: MIP is only supported for chroma with DM_CHROMA.");
01844     CHECK(!coLocatedLumaPU.cu->mipFlag, "Error: Co-located luma CU should use MIP.");
01845 
01846     modeIdx       = coLocatedLumaPU.intraDir[CHANNEL_TYPE_LUMA];
01847     transposeFlag = coLocatedLumaPU.mipTransposedFlag;
01848   }
01849   const int bitDepth = pu.cu->slice->getSPS()->getBitDepth(toChannelType(compId));
01850 
01851   CHECK(modeIdx >= getNumModesMip(piPred), "Error: Wrong MIP mode index");
01852 
01853   static_vector<int, MIP_MAX_WIDTH* MIP_MAX_HEIGHT> predMip( piPred.width * piPred.height );
01854   m_matrixIntraPred.predBlock(predMip.data(), modeIdx, transposeFlag, bitDepth, compId);
01855 
01856   for( int y = 0; y < piPred.height; y++ )
01857   {
01858     for( int x = 0; x < piPred.width; x++ )
01859     {
01860       piPred.at( x, y ) = Pel(predMip[y * piPred.width + x]);
01861     }
01862   }
01863 }
01864 
01865 void IntraPrediction::reorderPLT(CodingStructure& cs, Partitioner& partitioner, ComponentID compBegin, uint32_t numComp)
01866 {
01867   CodingUnit &cu = *cs.getCU(partitioner.chType);
01868 
01869   uint8_t        reusePLTSizetmp = 0;
01870   uint8_t        pltSizetmp = 0;
01871   Pel            curPLTtmp[MAX_NUM_COMPONENT][MAXPLTSIZE];
01872   bool           curPLTpred[MAXPLTPREDSIZE];
01873 
01874   for (int idx = 0; idx < MAXPLTPREDSIZE; idx++)
01875   {
01876     curPLTpred[idx] = false;
01877     cu.reuseflag[compBegin][idx] = false;
01878   }
01879   for (int idx = 0; idx < MAXPLTSIZE; idx++)
01880   {
01881     curPLTpred[idx] = false;
01882   }
01883 
01884   for (int predidx = 0; predidx < cs.prevPLT.curPLTSize[compBegin]; predidx++)
01885   {
01886     bool match = false;
01887     int curidx = 0;
01888 
01889     for (curidx = 0; curidx < cu.curPLTSize[compBegin]; curidx++)
01890     {
01891       if( curPLTpred[curidx] )
01892       {
01893         continue;
01894       }
01895       bool matchTmp = true;
01896       for (int comp = compBegin; comp < (compBegin + numComp); comp++)
01897       {
01898         matchTmp = matchTmp && (cu.curPLT[comp][curidx] == cs.prevPLT.curPLT[comp][predidx]);
01899       }
01900       if (matchTmp)
01901       {
01902         match = true;
01903         break;
01904       }
01905     }
01906 
01907     if (match)
01908     {
01909       cu.reuseflag[compBegin][predidx] = true;
01910       curPLTpred[curidx] = true;
01911       if( cu.isLocalSepTree() )
01912       {
01913         cu.reuseflag[COMPONENT_Y][predidx] = true;
01914         for( int comp = COMPONENT_Y; comp < MAX_NUM_COMPONENT; comp++ )
01915         {
01916           curPLTtmp[comp][reusePLTSizetmp] = cs.prevPLT.curPLT[comp][predidx];
01917         }
01918       }
01919       else
01920       {
01921         for (int comp = compBegin; comp < (compBegin + numComp); comp++)
01922         {
01923           curPLTtmp[comp][reusePLTSizetmp] = cs.prevPLT.curPLT[comp][predidx];
01924         }
01925       }
01926       reusePLTSizetmp++;
01927       pltSizetmp++;
01928     }
01929   }
01930   cu.reusePLTSize[compBegin] = reusePLTSizetmp;
01931   for (int curidx = 0; curidx < cu.curPLTSize[compBegin]; curidx++)
01932   {
01933     if (!curPLTpred[curidx])
01934     {
01935       if( cu.isLocalSepTree() )
01936       {
01937         for( int comp = compBegin; comp < (compBegin + numComp); comp++ )
01938         {
01939           curPLTtmp[comp][pltSizetmp] = cu.curPLT[comp][curidx];
01940         }
01941         if( isLuma(partitioner.chType) )
01942         {
01943           curPLTtmp[COMPONENT_Cb][pltSizetmp] = 1 << (cs.sps->getBitDepth(CHANNEL_TYPE_CHROMA) - 1);
01944           curPLTtmp[COMPONENT_Cr][pltSizetmp] = 1 << (cs.sps->getBitDepth(CHANNEL_TYPE_CHROMA) - 1);
01945         }
01946         else
01947         {
01948           curPLTtmp[COMPONENT_Y][pltSizetmp] = 1 << (cs.sps->getBitDepth(CHANNEL_TYPE_LUMA) - 1);
01949         }
01950       }
01951       else
01952       {
01953         for (int comp = compBegin; comp < (compBegin + numComp); comp++)
01954         {
01955           curPLTtmp[comp][pltSizetmp] = cu.curPLT[comp][curidx];
01956         }
01957       }
01958       pltSizetmp++;
01959     }
01960   }
01961   assert(pltSizetmp == cu.curPLTSize[compBegin]);
01962   for (int curidx = 0; curidx < cu.curPLTSize[compBegin]; curidx++)
01963   {
01964     if( cu.isLocalSepTree() )
01965     {
01966       for( int comp = COMPONENT_Y; comp < MAX_NUM_COMPONENT; comp++ )
01967       {
01968         cu.curPLT[comp][curidx] = curPLTtmp[comp][curidx];
01969       }
01970     }
01971     else
01972     {
01973       for (int comp = compBegin; comp < (compBegin + numComp); comp++)
01974       {
01975         cu.curPLT[comp][curidx] = curPLTtmp[comp][curidx];
01976       }
01977     }
01978   }
01979 }
